from __future__ import annotations


LANGUAGES = (
    ("en", "English"),
    ("zh_TW", "繁體中文"),
    ("zh_CN", "简体中文"),
    ("ko", "한국어"),
)

_language = "en"


def set_language(code: str) -> None:
    global _language
    valid = {value for value, _label in LANGUAGES}
    _language = code if code in valid else "en"


def get_language() -> str:
    return _language


def tr(text: str, **values) -> str:
    translated = _TRANSLATIONS.get(_language, {}).get(text, text)
    return translated.format(**values) if values else translated


def source_text(text: str, language: str) -> str | None:
    if language == "en":
        keys = {key for translations in _TRANSLATIONS.values() for key in translations}
        return text if text in keys else None
    for source, translated in _TRANSLATIONS.get(language, {}).items():
        if translated == text:
            return source
    return None


def retranslate_widgets(root, old_language: str) -> None:
    pending = [root]
    while pending:
        widget = pending.pop()
        pending.extend(widget.winfo_children())
        try:
            text = widget.cget("text")
        except Exception:
            continue
        source = source_text(str(text), old_language)
        if source is not None:
            try:
                widget.configure(text=tr(source))
            except Exception:
                pass


